import { getJson, postJson } from '../../api/http';

// A project's tasks under a key nested beneath ['projects'] so invalidating projects refreshes them
// too (CLAUDE.md rule 5). Each task carries a title and a done flag.
export type Task = { id: number; projectId: number; title: string; done: boolean };

export const projectTasksKey = (projectId: number) =>
  ['projects', projectId, 'tasks'] as const;

// The URL key the "open vs finished" filter owns (CLAUDE.md rule 4). '' = all tasks, 'OPEN' = only
// not-done, 'DONE' = only done. The control (filter.slot.tsx) writes it; the table reads the same
// key to drop rows at the other status — no callback, no shared state, just the key.
export const TASK_FILTER_PARAM = 'taskFilter';
export const TASK_FILTERS = ['OPEN', 'DONE'] as const;

export function fetchProjectTasks(projectId: number): Promise<Task[]> {
  return getJson<Task[]>(`/api/projects/${projectId}/tasks`);
}

/** Tick a task off (or back on); the server flips its done flag and records the audited side-effect. */
export function toggleTask(taskId: number): Promise<Task> {
  return postJson<Task>(`/api/tasks/${taskId}/toggle`, {});
}
===tasks/ProjectTasksTable.tsx===
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  projectTasksKey,
  fetchProjectTasks,
  toggleTask,
  TASK_FILTER_PARAM,
  type Task,
} from './queries';
import { ProjectTasksToolbar } from '../../slots/defs/projectTasksToolbar';
import { useSearchParam, asString } from '../../url/useSearchParam';

// A project's task checklist. Queries for itself under ['projects', projectId, 'tasks'] — never
// handed its data by a parent (CLAUDE.md rule 5). Ticking a task off is a mutation that invalidates
// the same key so the row (and its status cell) refresh themselves (rule 5); the audited record is
// written server-side. Carries the stable data-testid contract: the table, a row per task, the
// title/status cells and the per-row toggle button the test reads.
export function ProjectTasksTable({ projectId }: { projectId: number }) {
  const queryClient = useQueryClient();
  const { data: tasks } = useQuery({
    queryKey: projectTasksKey(projectId),
    queryFn: () => fetchProjectTasks(projectId),
  });
  const mutation = useMutation({
    mutationFn: (taskId: number) => toggleTask(taskId),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: projectTasksKey(projectId) });
    },
  });

  const [filter] = useSearchParam(TASK_FILTER_PARAM, asString);

  if (!tasks) {
    return null;
  }

  // Reads the shared `taskFilter` key (rule 4) to show just the open, just the finished, or all
  // tasks. The filter control (filter.slot.tsx) writes the same key.
  const shown =
    filter === 'OPEN'
      ? tasks.filter((task: Task) => !task.done)
      : filter === 'DONE'
        ? tasks.filter((task: Task) => task.done)
        : tasks;

  return (
    <>
    <ProjectTasksToolbar.Slot />
    <table data-testid="project-tasks-table">
      <thead>
        <tr>
          <th>Task</th>
          <th>Status</th>
          <th />
        </tr>
      </thead>
      <tbody>
        {shown.map((task: Task) => (
          <tr key={task.id} data-testid={`task-row-${task.id}`}>
            <td data-testid="task-title">{task.title}</td>
            <td data-testid="task-status">{task.done ? 'DONE' : 'OPEN'}</td>
            <td>
              <button
                data-testid={`task-toggle-${task.id}`}
                type="button"
                onClick={() => mutation.mutate(task.id)}
              >
                {task.done ? 'Reopen' : 'Tick off'}
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
    </>
  );
}
===contacts/queries.ts===
import { getJson, postJson } from '../../api/http';

// A client's contacts under a key nested beneath ['clients'] so invalidating clients refreshes them
// too (CLAUDE.md rule 5). Each contact carries a name, an email and a role.
export type Contact = { id: number; name: string; email: string; role: string };

export const clientContactsKey = (clientId: number) =>
  ['clients', clientId, 'contacts'] as const;

// A "proper email address": one @, non-empty local and domain parts, and a dotted domain. Shared by
// the form and mirrored by the server so a malformed address can never be saved.
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isValidEmail(email: string): boolean {
  return EMAIL_PATTERN.test(email.trim());
}

export function fetchClientContacts(clientId: number): Promise<Contact[]> {
  return getJson<Contact[]>(`/api/clients/${clientId}/contacts`);
}

export function createContact(input: {
  name: string;
  email: string;
  role: string;
  clientId: number;
}): Promise<Contact> {
  return postJson<Contact>('/api/contacts', input);
}
